function navigacija( $dabartinis = '' ) {
		$langai = array(
			'ps-katalogas' => 'Katalogas',
			'ps-akcijos'   => 'Akcijos',
			'ps-gavimas'   => 'Gavimas',
			'ps-tiekimas'  => 'Tiekimas',
			'ps-desk'      => 'Užsakymai',
		);
		$out = '';
		foreach ( $langai as $slug => $vardas ) {
			$out .= '<a class="' . ( $slug === $dabartinis ? 'on' : '' ) . '" href="'
				. esc_url( admin_url( 'admin.php?page=' . $slug ) ) . '">' . esc_html( $vardas ) . '</a>';
		}
		return $out;
	}

